import XCTest
import simd
@testable import MacVisualizerCore

final class ParticleVisualizerTests: XCTestCase {
    private func frame(bands: [Float], t: TimeInterval) -> AudioFrame {
        AudioFrame(bands: bands, bandPeaks: bands, waveform: [], rms: 0, peak: 0, timestamp: t)
    }
    private let loud = [Float](repeating: 1.0, count: 24)
    private let quiet = [Float](repeating: 0.0, count: 24)

    /// Settings whose capacity matches a test's init capacity so the visualizer's
    /// settings-driven reconciliation does not reallocate mid-test.
    private func settings(maxParticles: Int) -> VisualizerSettings {
        var s = VisualizerSettings.defaults
        s.particlesMaxParticles = maxParticles
        return s
    }

    func testVertexCountIsSixPerParticle() {
        let v = ParticleVisualizer(count: 50).makeVertices(frame: frame(bands: quiet, t: 0),
                                                            settings: settings(maxParticles: 50), aspect: 1)
        XCTAssertEqual(v.count, 50 * 6)
    }

    func testVerticesStayInClipSpace() {
        let viz = ParticleVisualizer(count: 200)
        let s = settings(maxParticles: 200)
        var t = 0.0
        for _ in 0..<120 {
            let v = viz.makeVertices(frame: frame(bands: loud, t: t), settings: s, aspect: 1.6)
            for vert in v {
                XCTAssertLessThanOrEqual(abs(vert.position.x), 1.25)
                XCTAssertLessThanOrEqual(abs(vert.position.y), 1.25)
            }
            t += 1.0 / 60.0
        }
    }

    func testDeterministicForSameSeedAndCalls() {
        let a = ParticleVisualizer(count: 64, seed: 12345)
        let b = ParticleVisualizer(count: 64, seed: 12345)
        let s = settings(maxParticles: 64)
        var t = 0.0
        var lastA: [BarVertex] = [], lastB: [BarVertex] = []
        for _ in 0..<30 {
            lastA = a.makeVertices(frame: frame(bands: loud, t: t), settings: s, aspect: 1)
            lastB = b.makeVertices(frame: frame(bands: loud, t: t), settings: s, aspect: 1)
            t += 1.0 / 60.0
        }
        XCTAssertEqual(lastA, lastB)
    }

    func testBassRaisesTotalBrightnessVsSilence() {
        func totalBrightness(bands: [Float]) -> Float {
            let viz = ParticleVisualizer(count: 100, seed: 7)
            let s = settings(maxParticles: 100)
            var t = 0.0
            var sum: Float = 0
            for _ in 0..<20 {
                let v = viz.makeVertices(frame: frame(bands: bands, t: t), settings: s, aspect: 1)
                sum = v.reduce(0) { $0 + $1.color.x + $1.color.y + $1.color.z }
                t += 1.0 / 60.0
            }
            return sum
        }
        XCTAssertGreaterThan(totalBrightness(bands: loud), totalBrightness(bands: quiet))
    }

    func testBeatBoostMakesParticlesLargerForOneFrame() {
        let bands = [Float](repeating: 0.5, count: 24)
        let s = settings(maxParticles: 100)
        let baseFrame = AudioFrame(bands: bands, bandPeaks: bands, waveform: [],
                                   rms: 0.4, peak: 0.5, timestamp: 0)
        let beatFrame = AudioFrame(bands: bands, bandPeaks: bands, waveform: [],
                                   rms: 0.4, peak: 0.5, timestamp: 0,
                                   beat: true, beatIntensity: 1.0)
        let baseViz = ParticleVisualizer(count: 100, seed: 17)
        let boostViz = ParticleVisualizer(count: 100, seed: 17)
        // Warm both visualizers with one non-beat frame to align state.
        _ = baseViz.makeVertices(frame: baseFrame, settings: s, aspect: 1)
        _ = boostViz.makeVertices(frame: beatFrame, settings: s, aspect: 1)

        // Same next-frame input — the boosted one should still render visibly larger
        // quads because the boost decays gradually.
        let t1 = AudioFrame(bands: bands, bandPeaks: bands, waveform: [], rms: 0.4, peak: 0.5, timestamp: 1.0/60)
        let baseVerts = baseViz.makeVertices(frame: t1, settings: s, aspect: 1)
        let boostVerts = boostViz.makeVertices(frame: t1, settings: s, aspect: 1)
        // Same vertex count (same particle count), but the x-extents on the boosted
        // visualizer should be wider on average.
        func avgWidth(_ verts: [BarVertex]) -> Float {
            guard !verts.isEmpty else { return 0 }
            var total: Float = 0; var n = 0
            for i in stride(from: 0, to: verts.count - 5, by: 6) {
                let xs = [verts[i].position.x, verts[i+1].position.x, verts[i+2].position.x]
                let xmin = xs.min() ?? 0; let xmax = xs.max() ?? 0
                total += (xmax - xmin); n += 1
            }
            return n > 0 ? total / Float(n) : 0
        }
        XCTAssertGreaterThan(avgWidth(boostVerts), avgWidth(baseVerts))
    }

    // MARK: - Value-preservation golden (bit-exact, captured from base behavior)

    // Flattened [position.x, position.y, color.r, color.g, color.b, color.a] of every
    // emitted vertex (Float little-endian bit patterns, base64), captured from the BASE
    // ParticleVisualizer at VisualizerSettings.defaults driving a fixed seeded frame
    // sequence (seed 0xABCDEF12, capacity 200, 24 bands all at 0.8 so bass 0.8 > the 0.5
    // threshold fires the impulse/brightness/size paths every frame, t = k/60, beat at
    // frame 10 with intensity 0.8, aspect 1.5). BEAT = emitted vertices at the beat frame
    // (k=10); FINAL = vertices after the full sequence (k=20). Accumulated stateful
    // physics + a beat frame + the bass path catch drift, damping, return-lerp, bass
    // impulse/brightness/size, beat boost, respawn-RNG, color, and capacity regressions.
    private static let beatGolden = ""
    private static let finalGolden = ""

    /// Replays the exact base-capture frame sequence and returns the emitted vertices
    /// at the beat frame (k=10) and the final frame (k=20).
    private func goldenRun() -> (beat: [BarVertex], final: [BarVertex]) {
        let viz = ParticleVisualizer(count: 200, seed: 0xABCDEF12)
        let bands = [Float](repeating: 0.8, count: 24)
        var beat: [BarVertex] = [], final: [BarVertex] = []
        for k in 0...20 {
            let t = Double(k) / 60.0
            let isBeat = (k == 10)
            let f = AudioFrame(bands: bands, bandPeaks: bands, waveform: [],
                               rms: 0.4, peak: 0.5, timestamp: t,
                               beat: isBeat, beatIntensity: isBeat ? 0.8 : 0)
            let out = viz.makeVertices(frame: f, settings: .defaults, aspect: 1.5)
            if k == 10 { beat = out }
            if k == 20 { final = out }
        }
        return (beat, final)
    }

    private func assertMatchesGolden(_ out: [BarVertex], _ base64: String, _ label: String) {
        let golden = Data(base64Encoded: base64)!.withUnsafeBytes { Array($0.bindMemory(to: Float.self)) }
        XCTAssertEqual(golden.count, out.count * 6, "\(label) vertex count")
        for (i, v) in out.enumerated() {
            let b = i * 6
            XCTAssertEqual(v.position.x.bitPattern, golden[b + 0].bitPattern, "\(label) position.x @ \(i)")
            XCTAssertEqual(v.position.y.bitPattern, golden[b + 1].bitPattern, "\(label) position.y @ \(i)")
            XCTAssertEqual(v.color.x.bitPattern,    golden[b + 2].bitPattern, "\(label) color.r @ \(i)")
            XCTAssertEqual(v.color.y.bitPattern,    golden[b + 3].bitPattern, "\(label) color.g @ \(i)")
            XCTAssertEqual(v.color.z.bitPattern,    golden[b + 4].bitPattern, "\(label) color.b @ \(i)")
            XCTAssertEqual(v.color.w.bitPattern,    golden[b + 5].bitPattern, "\(label) color.a @ \(i)")
        }
    }

    func testDefaultBeatFrameOutputUnchanged() {
        assertMatchesGolden(goldenRun().beat, Self.beatGolden, "beat")
    }

    func testDefaultFinalFrameOutputUnchanged() {
        assertMatchesGolden(goldenRun().final, Self.finalGolden, "final")
    }

    // MARK: - Field-read & helpers

    /// Runs `frames` of identical `bands` through a fresh visualizer under settings
    /// produced by `configure`, returning the last emit. Capacity is pinned to `cap`
    /// (both init and settings) unless `configure` overrides particlesMaxParticles.
    private func run(_ configure: (inout VisualizerSettings) -> Void,
                     bands customBands: [Float]? = nil, frames: Int = 40,
                     seed: UInt64 = 9, cap: Int = 120, aspect: Float = 1) -> [BarVertex] {
        var s = VisualizerSettings.defaults
        s.particlesMaxParticles = cap
        configure(&s)
        let viz = ParticleVisualizer(count: cap, seed: seed)
        let b = customBands ?? loud
        var t = 0.0, last: [BarVertex] = []
        for _ in 0..<frames {
            last = viz.makeVertices(frame: frame(bands: b, t: t), settings: s, aspect: aspect)
            t += 1.0 / 60.0
        }
        return last
    }
    private func xSpan(_ v: [BarVertex]) -> Float { (v.map(\.position.x).max() ?? 0) - (v.map(\.position.x).min() ?? 0) }
    private func totalBrightness(_ v: [BarVertex]) -> Float { v.reduce(0) { $0 + $1.color.x + $1.color.y + $1.color.z } }
    private func allFinite(_ v: [BarVertex]) -> Bool {
        v.allSatisfy { $0.position.x.isFinite && $0.position.y.isFinite && $0.color.x.isFinite }
    }
    /// Stronger than `allFinite`: every emitted position component AND every color
    /// component must be finite (a NaN/inf in any one poisons rendering).
    private func clean(_ v: [BarVertex]) -> Bool {
        v.allSatisfy {
            $0.position.x.isFinite && $0.position.y.isFinite
                && $0.color.x.isFinite && $0.color.y.isFinite
                && $0.color.z.isFinite && $0.color.w.isFinite
        }
    }
    /// Maximum signed-distance of any vertex from the origin — proxy for how far the
    /// bass impulse has flung particles outward.
    private func maxExtent(_ v: [BarVertex]) -> Float { v.map { max(abs($0.position.x), abs($0.position.y)) }.max() ?? 0 }

    // MARK: - Field-read tests (each tunable actually drives output)

    func testBaseSizeScalesQuad() {
        XCTAssertGreaterThan(xSpan(run({ $0.particlesBaseSize = 0.04 }, bands: quiet)),
                             xSpan(run({ $0.particlesBaseSize = 0.001 }, bands: quiet)))
    }
    func testBaseBrightnessRaisesBrightness() {
        XCTAssertGreaterThan(totalBrightness(run({ $0.particlesBaseBrightness = 0.9 }, bands: quiet)),
                             totalBrightness(run({ $0.particlesBaseBrightness = 0.1 }, bands: quiet)))
    }
    func testBassImpulseFlingsParticlesFartherOutward() {
        // A larger outward impulse moves particles farther from center before respawn.
        XCTAssertGreaterThan(maxExtent(run({ $0.particlesBassImpulse = 1.5 }, frames: 6, seed: 3)),
                             maxExtent(run({ $0.particlesBassImpulse = 0.0 }, frames: 6, seed: 3)))
    }
    func testBassBrightnessGainRaisesBrightnessUnderBass() {
        XCTAssertGreaterThan(totalBrightness(run({ $0.particlesBassBrightnessGain = 2.5 }, frames: 6)),
                             totalBrightness(run({ $0.particlesBassBrightnessGain = 0.0 }, frames: 6)))
    }
    func testBassSizeGainGrowsParticlesUnderBass() {
        XCTAssertGreaterThan(xSpan(run({ $0.particlesBassSizeGain = 4.0; $0.particlesSizeCapMultiplier = 8 }, frames: 6)),
                             xSpan(run({ $0.particlesBassSizeGain = 0.0 }, frames: 6)))
    }
    func testBassThresholdAboveBassSuppressesImpulse() {
        // Threshold above the bass level (0.8) blocks the impulse entirely; the field
        // stays near its initial spread instead of being flung outward.
        let suppressed = maxExtent(run({ $0.particlesBassThreshold = 1.0 }, frames: 8, seed: 3))
        let active = maxExtent(run({ $0.particlesBassThreshold = 0.0 }, frames: 8, seed: 3))
        XCTAssertGreaterThan(active, suppressed)
    }
    func testInitialVelocityScaleAffectsInitialField() {
        // Higher initial velocity spreads the field faster across the first few frames.
        let fast = maxExtent(run({ $0.particlesInitialVelocityScale = 0.5; $0.particlesBassThreshold = 2 }, frames: 4, seed: 11))
        let slow = maxExtent(run({ $0.particlesInitialVelocityScale = 0.0; $0.particlesBassThreshold = 2 }, frames: 4, seed: 11))
        XCTAssertGreaterThan(fast, slow)
    }
    func testBrightnessCapLimitsBrightness() {
        // A low cap clips brightness below an uncapped (cap 2) run under heavy bass.
        XCTAssertLessThan(totalBrightness(run({ $0.particlesBrightnessCap = 0.2 }, frames: 8)),
                          totalBrightness(run({ $0.particlesBrightnessCap = 2.0 }, frames: 8)))
    }
    func testLowBandPercentChangesBassAveraging() {
        // Lower bands silent, upper bands loud. Averaging only the lowest band yields ~0
        // bass; averaging all bands yields a high bass -> more bass-driven brightness.
        var split = [Float](repeating: 0.0, count: 24)
        for i in 12..<24 { split[i] = 1.0 }
        let narrow = totalBrightness(run({ $0.particlesLowBandPercent = 0.05; $0.particlesBassThreshold = 0.0; $0.particlesBrightnessCap = 2.0 },
                                         bands: split, frames: 6, seed: 3))
        let wide = totalBrightness(run({ $0.particlesLowBandPercent = 1.0; $0.particlesBassThreshold = 0.0; $0.particlesBrightnessCap = 2.0 },
                                       bands: split, frames: 6, seed: 3))
        XCTAssertGreaterThan(wide, narrow)
    }
    func testBeatHalfLifeControlsBoostDecay() {
        func boostedWidthNextFrame(_ halfLife: Double) -> Float {
            var s = VisualizerSettings.defaults
            s.particlesMaxParticles = 100
            s.particlesBeatHalfLife = halfLife
            let viz = ParticleVisualizer(count: 100, seed: 17)
            let bands = [Float](repeating: 0.3, count: 24)   // below threshold; isolate beat
            func mk(_ t: Double, beat: Bool) -> AudioFrame {
                AudioFrame(bands: bands, bandPeaks: bands, waveform: [], rms: 0.2, peak: 0.3,
                           timestamp: t, beat: beat, beatIntensity: beat ? 1.0 : 0)
            }
            _ = viz.makeVertices(frame: mk(0, beat: true), settings: s, aspect: 1)
            let v = viz.makeVertices(frame: mk(0.1, beat: false), settings: s, aspect: 1)
            return xSpan(v)
        }
        // A longer half-life retains more boost after 100ms -> wider quads.
        XCTAssertGreaterThan(boostedWidthNextFrame(2.0), boostedWidthNextFrame(0.02))
    }

    // MARK: - maxParticles stateful reallocation

    func testMaxParticlesDrivesCapacityFromSettings() {
        // init capacity differs from settings; the visualizer reconciles to settings.
        let viz = ParticleVisualizer(count: 600, seed: 3)
        var s = VisualizerSettings.defaults
        s.particlesMaxParticles = 60
        let v = viz.makeVertices(frame: frame(bands: loud, t: 0), settings: s, aspect: 1)
        XCTAssertEqual(v.count, 60 * 6)
    }
    func testMaxParticlesReallocCanGrowAndShrinkAcrossFrames() {
        let viz = ParticleVisualizer(count: 200, seed: 3)
        var s = VisualizerSettings.defaults
        var t = 0.0
        func step(_ cap: Int, _ n: Int) -> [BarVertex] {
            s.particlesMaxParticles = cap
            var last: [BarVertex] = []
            for _ in 0..<n { last = viz.makeVertices(frame: frame(bands: loud, t: t), settings: s, aspect: 1); t += 1.0/60.0 }
            return last
        }
        let grown = step(800, 5)
        XCTAssertEqual(grown.count, 800 * 6)
        let shrunk = step(40, 5)
        XCTAssertEqual(shrunk.count, 40 * 6)
        XCTAssertTrue(allFinite(shrunk))
    }

    // MARK: - Clamp tests (persisted/edited out-of-range values snap to nearest bound)

    func testMaxParticlesZeroClampsToOneNoCrash() {
        let v = run({ $0.particlesMaxParticles = 0 }, frames: 10, cap: 0)
        XCTAssertEqual(v.count, 6)            // capacity clamped to 1 -> exactly one particle
        XCTAssertTrue(allFinite(v))
    }
    func testMaxParticlesNegativeClampsToOne() {
        XCTAssertEqual(run({ $0.particlesMaxParticles = -50 }, frames: 10, cap: 1).count,
                       run({ $0.particlesMaxParticles = 1 }, frames: 10, cap: 1).count)
    }
    func testMaxParticlesCapsAtFourThousand() {
        let big = run({ $0.particlesMaxParticles = 10000 }, frames: 2, cap: 4000)
        let cap = run({ $0.particlesMaxParticles = 4000 }, frames: 2, cap: 4000)
        XCTAssertEqual(big.count, 4000 * 6)
        XCTAssertEqual(cap.count, 4000 * 6)
    }
    func testBaseSizeNegativeClampsToZero() {
        XCTAssertEqual(xSpan(run({ $0.particlesBaseSize = -1 }, bands: quiet)),
                       xSpan(run({ $0.particlesBaseSize = 0 }, bands: quiet)), accuracy: 0)
    }
    func testBaseBrightnessClampsToUnitRange() {
        XCTAssertEqual(totalBrightness(run({ $0.particlesBaseBrightness = 5 }, bands: quiet)),
                       totalBrightness(run({ $0.particlesBaseBrightness = 1 }, bands: quiet)), accuracy: 1e-4)
        XCTAssertEqual(totalBrightness(run({ $0.particlesBaseBrightness = -5 }, bands: quiet)),
                       totalBrightness(run({ $0.particlesBaseBrightness = 0 }, bands: quiet)), accuracy: 1e-4)
    }
    func testVelocityDampingClampsToUnitRange() {
        // Damping > 1 would amplify velocity unboundedly; must clamp to 1. < 0 clamps to 0.
        XCTAssertTrue(allFinite(run({ $0.particlesVelocityDamping = 9 }, frames: 30)))
        XCTAssertEqual(run({ $0.particlesVelocityDamping = -1 }, frames: 10),
                       run({ $0.particlesVelocityDamping = 0 }, frames: 10))
    }
    func testReturnLerpRateNegativeClampsToZero() {
        XCTAssertEqual(run({ $0.particlesReturnLerpRate = -5 }, frames: 10),
                       run({ $0.particlesReturnLerpRate = 0 }, frames: 10))
    }
    func testBeatHalfLifeZeroStaysFinite() {
        XCTAssertTrue(allFinite(run({ $0.particlesBeatHalfLife = 0 }, frames: 10)))
        XCTAssertTrue(allFinite(run({ $0.particlesBeatHalfLife = -1 }, frames: 10)))
    }
    func testBrightnessCapNegativeClampsToZero() {
        // Cap < 0 clamps to 0; min(0, ...) under bass yields no positive brightness.
        XCTAssertTrue(allFinite(run({ $0.particlesBrightnessCap = -3 }, frames: 10)))
    }
    func testSizeCapMultiplierNegativeStaysFinite() {
        XCTAssertTrue(allFinite(run({ $0.particlesSizeCapMultiplier = -3 }, frames: 10)))
    }
    func testRespawnOffscreenBoundPositiveStaysFinite() {
        // Bound <= 0 would respawn every particle every frame; clamp keeps it > 0.
        XCTAssertTrue(allFinite(run({ $0.particlesRespawnOffscreenBound = 0 }, frames: 20)))
        XCTAssertTrue(allFinite(run({ $0.particlesRespawnOffscreenBound = -5 }, frames: 20)))
    }
    func testRespawnCenterHalfRangeNegativeStaysFinite() {
        XCTAssertTrue(allFinite(run({ $0.particlesRespawnCenterHalfRange = -1 }, frames: 30)))
    }

    func testPathologicalLowBandPercentDoesNotTrapAndStaysBounded() {
        // A persisted/edited huge percent (1e308) would make Int(bands.count * percent)
        // TRAP. The percent is clamped finite and the band count saturates to 1...count,
        // so the visualizer stays crash-free and bounded, and the bass average is valid.
        let v = run({ $0.particlesLowBandPercent = 1e308 }, frames: 8)
        XCTAssertFalse(v.isEmpty)
        XCTAssertTrue(allFinite(v))
        // NaN-ish percent (also non-finite) must be safe too.
        let v2 = run({ $0.particlesLowBandPercent = -1e308 }, frames: 8)
        XCTAssertTrue(allFinite(v2))
    }

    // MARK: - Non-finite sanitization (NaN/inf must never poison state)

    /// Every clamped/free float field must finite-sanitize before use: a persisted or
    /// in-memory NaN/±inf falls back to that field's default, so no NaN/inf ever reaches
    /// an emitted vertex position, size, or color (Swift's min/max do NOT drop NaN).
    func testNonFiniteFloatFieldsNeverPoisonOutput() {
        let paths: [WritableKeyPath<VisualizerSettings, Double>] = [
            \.particlesInitialVelocityScale, \.particlesRespawnVelocityScale, \.particlesBaseSize,
            \.particlesBaseBrightness, \.particlesBrightnessJitter, \.particlesBassThreshold,
            \.particlesVelocityDamping, \.particlesReturnLerpRate, \.particlesBeatHalfLife,
            \.particlesBeatPulseScale, \.particlesBassImpulse, \.particlesBassBrightnessGain,
            \.particlesBrightnessCap, \.particlesBassSizeGain, \.particlesSizeCapMultiplier,
            \.particlesRespawnOffscreenBound, \.particlesRespawnCenterHalfRange,
        ]
        for bad in [Double.nan, .infinity, -.infinity] {
            for kp in paths {
                // 30 frames so a field that poisons persistent state (e.g. velocity
                // damping) has time to corrupt the field before we inspect it.
                let v = run({ $0[keyPath: kp] = bad }, frames: 30, seed: 3)
                XCTAssertTrue(clean(v), "field \(kp) = \(bad) poisoned output")
            }
        }
    }

    /// beatHalfLife = .nan would make `realDt / beatHalfLife` NaN, poisoning beatBoost
    /// and thus every particle size on the next frame. The finite guard prevents it.
    func testBeatHalfLifeNonFiniteDoesNotPoison() {
        for bad in [Double.nan, .infinity, -.infinity] {
            var s = VisualizerSettings.defaults
            s.particlesMaxParticles = 100
            s.particlesBeatHalfLife = bad
            let viz = ParticleVisualizer(count: 100, seed: 17)
            let bands = [Float](repeating: 0.5, count: 24)
            func mk(_ t: Double, beat: Bool) -> AudioFrame {
                AudioFrame(bands: bands, bandPeaks: bands, waveform: [], rms: 0.4, peak: 0.5,
                           timestamp: t, beat: beat, beatIntensity: beat ? 1.0 : 0)
            }
            _ = viz.makeVertices(frame: mk(0, beat: true), settings: s, aspect: 1)
            let v = viz.makeVertices(frame: mk(0.1, beat: false), settings: s, aspect: 1)
            XCTAssertTrue(clean(v), "beatHalfLife = \(bad) poisoned output")
        }
    }

    // MARK: - Defaults are not clamped (sanity)

    func testDefaultsNotClampedToBounds() {
        XCTAssertNotEqual(run({ $0.particlesBassImpulse = 0 }, frames: 6, seed: 3),
                          run({ _ in }, frames: 6, seed: 3))            // default impulse 0.25 != 0
    }

    // MARK: - Adaptive bass trigger (quiet music)

    /// Runs `frames` frames at 60 fps where the bass sits at `base` and spikes to
    /// `spike` for 3 frames every half second; returns the last spike frame's vertices.
    private func runQuietMusic(base: Float, spike: Float, frames: Int = 123) -> [BarVertex] {
        let viz = ParticleVisualizer(count: 100, seed: 7)
        let s = settings(maxParticles: 100)
        var out: [BarVertex] = []
        for i in 0..<frames {
            let level = (i % 30) < 3 ? spike : base
            out = viz.makeVertices(frame: frame(bands: [Float](repeating: level, count: 24),
                                                t: Double(i) / 60.0),
                                   settings: s, aspect: 1)
        }
        return out
    }

    private func sumBrightness(_ v: [BarVertex]) -> Float {
        v.reduce(0) { $0 + $1.color.x + $1.color.y + $1.color.z }
    }

    /// Quiet music whose beats never reach the absolute threshold (0.5) must still
    /// drive the particles: a beat that stands out from the running level triggers.
    func testBeatsBelowAbsoluteThresholdStillDriveParticles() {
        let withBeats = runQuietMusic(base: 0.30, spike: 0.45)
        let steady = runQuietMusic(base: 0.30, spike: 0.30)
        XCTAssertGreaterThan(sumBrightness(withBeats), sumBrightness(steady))
    }

    /// A steady level below the threshold is not a beat: it must not trigger, so the
    /// field is identical whatever that steady level is.
    func testSteadyLevelBelowThresholdDoesNotTrigger() {
        XCTAssertEqual(runQuietMusic(base: 0.30, spike: 0.30),
                       runQuietMusic(base: 0.10, spike: 0.10))
    }

    /// Near-silence noise must not trigger even when it flickers relative to itself.
    func testNoiseFloorFlickerDoesNotTrigger() {
        XCTAssertEqual(runQuietMusic(base: 0.01, spike: 0.03),
                       runQuietMusic(base: 0.01, spike: 0.01))
    }
}
